以下是使用Java编写的一个可能解决这个问题的算法：

```java
import java.util.ArrayDeque;
import java.util.Queue;

public class Maze {
    static char[][] maze = {
            {'0', '1', '1', '1'},
            {'0', '0', '0', '1'},
            {'1', '0', '1', '1'},
            {'1', '0', '0', '0'},
    };

    static int n = maze.length;
    static boolean[][] visited = new boolean[n][n];

    static class Point {
        int x, y, steps;

        Point(int x, int y, int steps) {
            this.x = x;
            this.y = y;
            this.steps = steps;
        }
    }

    static int[] dx = {-1, 1, 0, 0, -1, -1, 1, 1};
    static int[] dy = {0, 0, -1, 1, -1, 1, 1, -1};

    static boolean isValid(int x, int y) {
        if (x >= 0 && x < n && y >= 0 && y < n &&
                maze[x][y] == '0' && !visited[x][y]) {
            return true;
        }
        return false;
    }

    static int bfs() {
        Queue<Point> queue = new ArrayDeque<>();
        queue.add(new Point(0, 0, 1));
        visited[0][0] = true;

        while (!queue.isEmpty()) {
            Point cur = queue.poll();

            if (cur.x == n - 1 && cur.y == n - 1) {
                return cur.steps;
            }

            for (int i = 0; i < dx.length; i++) {
                int newX = cur.x + dx[i];
                int newY = cur.y + dy[i];

                if (isValid(newX, newY)) {
                    queue.add(new Point(newX, newY, cur.steps + 1));
                    visited[newX][newY] = true;
                }
            }
        }

        return -1;
    }

    public static void main(String[] args) {
        System.out.println("Shortest path length: " + bfs());
    }
}
```

请注意，这个解决方案不会输出路径的坐标。要输出路径的坐标，你需要稍微修改该算法以在 `Point` 类中存储路径信息（例如使用前一个坐标的指针），然后在找到解决方案时回溯这些指针以构建和输出坐标列表。

