                    break;
                case "ArrowDown":
                    if (tankRect.bottom + offset < gameBoardRect.bottom) {
                        tank.style.top = `${tank.offsetTop + offset}px`;
                    }
                    break;
                case "ArrowLeft":
                    if (tankRect.left - offset > gameBoardRect.left) {
                        tank.style.left = `${tank.offsetLeft - offset}px`;
                    }
                    break;
                case "ArrowRight":
                    if (tankRect.right + offset < gameBoardRect.right) {
                        tank.style.left = `${tank.offsetLeft + offset}px`;
                    }
                    break;
                default:
                    break;
            }
        }

        document.addEventListener('keydown', moveTank);
    </script>
</body>
</html>
