要使用GLSL生成带有小山丘的陆地噪声，我们可以使用Perlin噪声或Simplex噪声等梯度噪声。这里是一个简单的实现：

```glsl
#ifdef GL_ES
precision mediump float;
#endif

uniform float u_time;
uniform vec2 u_resolution;
uniform vec2 u_mouse;

// Perlin noise function
float perlin(vec2 p) {
    return fract(sin(dot(p, vec2(12.9898, 3.1415))) * 43758.5453);
}


// Smooth interpolation between values a and b
float lerp(float a, float b, float t) {
    return a + (b - a) * t;
}

// Smoothing function for Perlin noise
float fbm(vec2 p) {
    float scale = 1.0;
    float total = 0.0;
    float frequency = 1.0;
    float maxAmplitude = 0.0;

    for (int i = 0; i < 5; ++i) {
        total += perlin(p * frequency) * scale;
        maxAmplitude += scale;
        scale *= 0.5;
        frequency *= 2.0;
    }

    return total / maxAmplitude;
}

void main(void) {
    vec2 p = gl_FragCoord.xy / u_resolution.xy;

    // Terrain color
    vec3 baseColor = vec3(106.0 / 255.0, 52.0 / 255.0, 27.0 / 255.0);
    vec3 sandColor = vec3(184.0 / 255.0, 133.0 / 255.0, 87.0 / 255.0);
    vec3 grassColor = vec3(156.0 / 255.0, 186.0 / 255.0, 87.0 / 255.0);
    vec3 hillColor = vec3(120.0 / 255.0, 120.0 / 255.0, 120.0 / 255.0);

    // Create terrain noise value
    float n = fbm(vec2(p.x * 10.0, p.y * 10.0 + u_time));

    // Height-based color blending
    vec3 color = mix(grassColor, hillColor, smoothstep(0.3, 0.6, n));
    color = mix(sandColor, color, smoothstep(0.15, 0.3, n));
    color = mix(baseColor, color, smoothstep(0.0, 0.15, n));

    gl_FragColor = vec4(color, 1.0);
}
```

