Вот пример скрипта стрельбы на языке C#, который отвечает за создание и выстреливание объектов (например, пули) при нажатии на клавишу пробел:

```csharp
using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class Shooting : MonoBehaviour
{
    public GameObject bulletPrefab; // Префаб пули, который вы хотите создать и выстрелить
    public Transform firePoint; // Точка, из которой будет происходить выстрел
    public float bulletSpeed = 20f; // Скорость пули

    // Update is called once per frame
    void Update()
    {
        if (Input.GetKeyDown(KeyCode.Space))
        {
            Fire(); // Вызываем функцию стрельбы при нажатии на пробел
        }
    }

    void Fire()
    {
        GameObject bullet = Instantiate(bulletPrefab, firePoint.position, firePoint.rotation); // Создаем пулю на позиции firePoint
        Rigidbody2D rb = bullet.GetComponent<Rigidbody2D>(); // Получаем компонент Rigidbody2D пули
        rb.AddForce(firePoint.up * bulletSpeed, ForceMode2D.Impulse); // Задаем направление и силу выстрела
    }
}
```

Для реализации этои стрельбы, следуйте этим шагам:

1. Создайте объект пули (prefab) с компонентом Rigidbody2D и коллайдерами в Unity.
2. Создайте объект, из которого будет происходить стрельба (например, игрок или пушка), и добавьте ему компонент скрипта Shooting.
